use gpui_ai::cues::{self, Cue};

// One place to hang sound, haptics, or a notification. The library never plays
// anything itself: it says what happened and leaves the decision here.
let _cues = cues::observe(cx, |cue, _cx| match cue {
    Cue::ResponseSettled { succeeded: true, .. } => play("chime"),
    Cue::Copied => play("tick"),
    _ => {}
});
// Dropping the subscription stops the cues.

own-events.code:
use gpui_ai::prelude::*;

// Every event carries the application's own identifier rather than a row
// number. A list that reorders, filters, or loses a row while a decision is in
// flight still resolves to the thing it was about.
fn gate(&mut self, cx: &mut Context<Self>) -> impl IntoElement {
    ApprovalCard::new("deploy-2f9c", "Deploy build 2f9c to production")
        .decision(self.decisions.get("deploy-2f9c").copied().unwrap_or_default())
        .on_event(cx.listener(|this, event: &ApprovalEvent, _, cx| {
            let (id, decision) = match event {
                ApprovalEvent::Approved { id } | ApprovalEvent::ApprovedAlways { id } => {
                    (id.clone(), ApprovalDecision::Approved)
                }
                ApprovalEvent::Rejected { id } => (id.clone(), ApprovalDecision::Rejected),
            };
            this.decisions.insert(id, decision);
            cx.notify();
        }))
}

own-progressive.code:
use gpui_ai::prelude::*;

// The application owns the text and the lifecycle. It advances them from
// whatever its model client hands back; the component renders the snapshot and
// never asks for more.
struct Reply {
    answer: StreamedContent,
}

impl Reply {
    fn started() -> Self {
        Self { answer: StreamedContent::new() }
    }

    fn token(&mut self, chunk: &str) {
        self.answer.append(chunk);
    }

    fn finished(&mut self) {
        self.answer.finish();
    }

    fn refused(&mut self, why: &str) {
        self.answer.fail(why);
    }
}

start-window.code:
use gpui::{App, Application, WindowOptions, prelude::*};
use gpui_ai::prelude::*;
use gpui_component::Root;

struct Agent;

impl Render for Agent {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        ToolChip::new("edit", "Edit main.rs").status(ToolStatus::Running)
    }
}

fn main() {
    Application::new().run(|cx: &mut App| {
        gpui_ai::init(cx);

        cx.open_window(WindowOptions::default(), |window, cx| {
            let agent = cx.new(|_| Agent);
            // Root owns the theme, the rem size, and the layers dialogs and
            // popovers are drawn into. Every gpui-component app has one.
            cx.new(|cx| Root::new(agent.into(), window, cx))
        })
        .unwrap();
    });
}

theme-custom.code:
use gpui::App;
use gpui_component::theme::{Theme, ThemeConfig, ThemeMode, ThemeRegistry};
use std::rc::Rc;

/// Registers a theme pack and switches to one of the themes in it.
///
/// A pack is the same JSON the bundled themes use: a name and a `themes`
/// array, each entry declaring a mode, its colours, and optionally a radius,
/// a shadow flag, and a base font size.
fn install(pack: &str, name: &str, cx: &mut App) -> anyhow::Result<()> {
    ThemeRegistry::global_mut(cx).load_themes_from_str(pack)?;

    let config = ThemeRegistry::global(cx)
        .themes()
        .get(name)
        .cloned()
        .ok_or_else(|| anyhow::anyhow!("the pack declares no theme called {name}"))?;

    let mode = config.mode;
    let theme = Theme::global_mut(cx);
    match mode {
        ThemeMode::Dark => theme.dark_theme = config.clone(),
        _ => theme.light_theme = config.clone(),
    }
    Theme::change(mode, None, cx);
    restore_unset_metrics(&config, cx);
    Ok(())
}

/// Puts back the metrics the incoming theme does not mention.
///
/// Applying a theme writes only the metrics that theme names, and what it
/// leaves behind is the *previous* theme's value rather than the default. In
/// an application that installs one theme and keeps it that never shows. In
/// one that lets a person switch, a theme asking for 14px type leaves every
/// theme chosen after it at 14px until the process restarts.
fn restore_unset_metrics(config: &ThemeConfig, cx: &mut App) {
    let defaults = Theme::default();
    let theme = Theme::global_mut(cx);
    if config.font_size.is_none() {
        theme.font_size = defaults.font_size;
    }
    if config.mono_font_size.is_none() {
        theme.mono_font_size = defaults.mono_font_size;
    }
    if config.radius.is_none() {
        theme.radius = defaults.radius;
    }
    if config.radius_lg.is_none() {
        theme.radius_lg = defaults.radius_lg;
    }
    if config.shadow.is_none() {
        theme.shadow = defaults.shadow;
    }
    // The Base layer keeps its own copy of the radius, so a scrollbar would go
    // on painting with the corners the last theme gave it.
    Theme::sync_base(cx);
}

theme-tokens.code:
use gpui::prelude::*;
use gpui_component::ActiveTheme as _;

fn panel(cx: &App) -> impl IntoElement {
    div()
        // Every colour, radius and type style comes from the active theme.
        // There is no gpui-ai styling layer to override and no colour of its
        // own to disagree with yours.
        .bg(cx.theme().secondary)
        .border_1()
        .border_color(cx.theme().border)
        .rounded(cx.theme().radius)
        .text_color(cx.theme().muted_foreground)
        .child("Ran three tools")
}
